import{_ as e,o,c as a,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"Permission Model","description":"","frontmatter":{},"headers":[],"relativePath":"en/admin/permissions.md","filePath":"en/admin/permissions.md","lastUpdated":1786689844000}'),s={name:"en/admin/permissions.md"};function i(n,t,d,l,u,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="permission-model" tabindex="-1">Permission Model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission Model&quot;">​</a></h1><p>ZViewer&#39;s permission system is divided into four roles, from highest to lowest: <strong>root (super admin)</strong>, <strong>admin</strong>, <strong>user</strong>, and <strong>guest</strong>. The table below gives you a clear overview of what each role can and cannot do.</p><h2 id="four-tier-role-comparison" tabindex="-1">Four-Tier Role Comparison <a class="header-anchor" href="#four-tier-role-comparison" aria-label="Permalink to &quot;Four-Tier Role Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>root</th><th>admin</th><th>user</th><th>guest</th></tr></thead><tbody><tr><td>Access admin panel</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Approve user registrations</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Change other users&#39; roles</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Delete any user</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Delete any room</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Create rooms</td><td>Yes</td><td>Yes</td><td>Depends on settings</td><td>No</td></tr><tr><td>Full control of own room</td><td>Yes</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Join rooms to watch</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Send comments and danmaku</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Modify system settings</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Check and apply updates</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Manage server files</td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr></tbody></table><blockquote><p><strong>Quick reference</strong>: root has all permissions; admin can manage rooms and updates but cannot manage users; user can watch and interact, and may be able to create rooms; guest can only watch and interact, and cannot create rooms.</p></blockquote><hr><h2 id="registration-and-approval-process" tabindex="-1">Registration and Approval Process <a class="header-anchor" href="#registration-and-approval-process" aria-label="Permalink to &quot;Registration and Approval Process&quot;">​</a></h2><h3 id="three-registration-modes" tabindex="-1">Three Registration Modes <a class="header-anchor" href="#three-registration-modes" aria-label="Permalink to &quot;Three Registration Modes&quot;">​</a></h3><p>Admins can choose the registration mode in the &quot;Basic Settings&quot; section of the admin panel:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Open Registration (open)</strong></td><td>Anyone who registers is activated automatically and becomes a user role immediately</td></tr><tr><td><strong>Approval Registration (approval)</strong></td><td>After registration, the account enters a pending state and requires root approval before use</td></tr><tr><td><strong>Registration Closed (closed)</strong></td><td>The registration entry is disabled; new users cannot register</td></tr></tbody></table><h3 id="registration-steps" tabindex="-1">Registration Steps <a class="header-anchor" href="#registration-steps" aria-label="Permalink to &quot;Registration Steps&quot;">​</a></h3><ol><li>Go to the homepage and click the &quot;Register&quot; button</li><li>Fill in your username and password, then submit</li><li>Depending on the registration mode: <ul><li><strong>Open mode</strong>: Registration activates immediately; you can log in directly</li><li><strong>Approval mode</strong>: After registration, you will see a &quot;Waiting for Approval&quot; message; your role will be guest with limited functionality</li><li><strong>Closed mode</strong>: The registration entry is not visible on the page</li></ul></li></ol><h3 id="approval-operations-root-only" tabindex="-1">Approval Operations (root only) <a class="header-anchor" href="#approval-operations-root-only" aria-label="Permalink to &quot;Approval Operations (root only)&quot;">​</a></h3><ol><li>Go to the admin panel -&gt; &quot;User Management&quot; tab</li><li>Find users with the &quot;Pending&quot; status</li><li>Click the &quot;Approve&quot; button to upgrade the user to a full user role</li></ol><hr><h2 id="guest-identity" tabindex="-1">Guest Identity <a class="header-anchor" href="#guest-identity" aria-label="Permalink to &quot;Guest Identity&quot;">​</a></h2><h3 id="automatic-assignment" tabindex="-1">Automatic Assignment <a class="header-anchor" href="#automatic-assignment" aria-label="Permalink to &quot;Automatic Assignment&quot;">​</a></h3><p>When you visit ZViewer without logging in, the system automatically assigns you a <strong>guest</strong> identity. You can use the service without registering.</p><h3 id="what-guests-can-do" tabindex="-1">What Guests Can Do <a class="header-anchor" href="#what-guests-can-do" aria-label="Permalink to &quot;What Guests Can Do&quot;">​</a></h3><ul><li>Join existing rooms and watch videos</li><li>Send comments and danmaku</li></ul><h3 id="what-guests-cannot-do" tabindex="-1">What Guests Cannot Do <a class="header-anchor" href="#what-guests-cannot-do" aria-label="Permalink to &quot;What Guests Cannot Do&quot;">​</a></h3><ul><li>Create rooms</li><li>Access the admin panel</li><li>Modify personal profile</li></ul><h3 id="becoming-a-full-user" tabindex="-1">Becoming a Full User <a class="header-anchor" href="#becoming-a-full-user" aria-label="Permalink to &quot;Becoming a Full User&quot;">​</a></h3><p>If you want more features, you can:</p><ol><li>Click &quot;Login/Register&quot; on the page</li><li>Register a new account (if the registration mode is open, you become a user immediately)</li><li>After logging in, you will automatically gain more permissions</li></ol><hr><h2 id="room-creation-permission" tabindex="-1">Room Creation Permission <a class="header-anchor" href="#room-creation-permission" aria-label="Permalink to &quot;Room Creation Permission&quot;">​</a></h2><p>Admins can set who can create rooms in the &quot;Basic Settings&quot;:</p><ul><li><strong>Admin Only</strong>: Only root and admin roles can create rooms</li><li><strong>All Users</strong>: User role can also create rooms</li></ul><p>Guests cannot create rooms under any circumstances.</p><hr><h2 id="authentication-mechanism-overview" tabindex="-1">Authentication Mechanism Overview <a class="header-anchor" href="#authentication-mechanism-overview" aria-label="Permalink to &quot;Authentication Mechanism Overview&quot;">​</a></h2><p>ZViewer uses a <strong>dual-token</strong> mechanism to ensure security:</p><ul><li><strong>Access Token</strong>: Short-lived (default 15 minutes), used to authenticate every request</li><li><strong>Refresh Token</strong>: Long-lived (default 7 days), used to automatically renew the access token after it expires</li></ul><p>These tokens are stored in the browser via <strong>httpOnly Cookies</strong>, which regular JavaScript cannot read, effectively preventing XSS attacks from stealing tokens.</p><p>In short: you log in once, and the system remembers you for a period of time without requiring repeated password entry.</p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="cannot-create-rooms-after-registration" tabindex="-1">Cannot create rooms after registration <a class="header-anchor" href="#cannot-create-rooms-after-registration" aria-label="Permalink to &quot;Cannot create rooms after registration&quot;">​</a></h3><p>Possible reasons:</p><ol><li>Your role is <strong>guest</strong> (pending approval or newly registered). Root needs to approve you in the admin panel to upgrade you to <strong>user</strong></li><li>Room creation permission is set to &quot;Admin Only&quot; and you are a user role</li><li>The registration mode is &quot;Open Registration&quot; but the system did not activate correctly -- contact the administrator to check</li></ol><h3 id="how-to-make-a-user-an-admin" tabindex="-1">How to make a user an admin? <a class="header-anchor" href="#how-to-make-a-user-an-admin" aria-label="Permalink to &quot;How to make a user an admin?&quot;">​</a></h3><p>Only <strong>root</strong> can promote other users to admin:</p><ol><li>Go to the admin panel -&gt; &quot;User Management&quot; tab</li><li>Find the user</li><li>Click &quot;Change Role&quot;, select admin</li><li>Save</li></ol><h3 id="forgot-the-root-password" tabindex="-1">Forgot the root password? <a class="header-anchor" href="#forgot-the-root-password" aria-label="Permalink to &quot;Forgot the root password?&quot;">​</a></h3><p>If you lose access to the root account password, you can recover it using the following methods:</p><ol><li>If you have command-line access to the server, run a reset script or modify the database directly</li><li>If environment variables or initial configuration were set during deployment, refer to the deployment documentation for the reset method</li><li>Contact the server administrator to modify the user password directly in the database (requires knowledge of database operations)</li></ol>',47)])])}const g=e(s,[["render",i]]);export{m as __pageData,g as default};
